// Determine if this was triggered by cron or webhook
const items = $input.all();
const item = items[0]?.json || {};

// If webhook triggered, extract shipment data directly
if (item.event_type === 'shipment_shipped' || item.tracking) {
  return [{ json: { source: 'webhook', shipments: [item] } }];
}

// If cron triggered, set flag to fetch from API
return [{ json: { source: 'cron', shipments: [] } }];

// ──────────────────────────────────────────────
// Extract shipments with tracking from ShipBob orders
// ──────────────────────────────────────────────
const response = $input.first().json;
const orders = Array.isArray(response) ? response : (response.orders || [response]);
const shipments = [];

for (const order of orders) {
  if (!order.shipments || order.shipments.length === 0) continue;

  for (const shipment of order.shipments) {
    if (!shipment.tracking?.tracking_number) continue;

    shipments.push({
      shipbob_order_id: order.id,
      shopify_order_id: order.reference_id,
      order_number: order.order_number,
      tracking_number: shipment.tracking.tracking_number,
      tracking_url: shipment.tracking.tracking_url || '',
      carrier: shipment.tracking.carrier || 'Other',
      status: shipment.status,
      shipped_date: shipment.created_date
    });
  }
}

if (shipments.length === 0) {
  return []; // No items to process - workflow stops here cleanly
}

return shipments.map(s => ({ json: s }));

// ──────────────────────────────────────────────
// Process webhook shipment into standard format
// ──────────────────────────────────────────────
const item = $input.first().json;
const shipment = item.shipments?.[0] || item;

// Handle ShipBob webhook payload format
return [{
  json: {
    shipbob_order_id: shipment.order_id || item.order_id,
    shopify_order_id: shipment.reference_id || item.reference_id,
    order_number: shipment.order_number || item.order_number,
    tracking_number: shipment.tracking?.tracking_number || shipment.tracking_number,
    tracking_url: shipment.tracking?.tracking_url || shipment.tracking_url || '',
    carrier: shipment.tracking?.carrier || shipment.carrier || 'Other',
    status: shipment.status || 'Completed',
    shipped_date: shipment.created_date || new Date().toISOString()
  }
}];

// ──────────────────────────────────────────────
// Check if this order already has a fulfillment with this tracking number
// Skip if already fulfilled to prevent duplicates
// ──────────────────────────────────────────────
const shipment = $('Merge Shipments').first().json;
const shopifyData = $input.first().json;
const order = shopifyData.order || shopifyData;

// Check if already fulfilled with this tracking number
const existingFulfillments = order.fulfillments || [];
const alreadyFulfilled = existingFulfillments.some(f => 
  f.tracking_numbers?.includes(shipment.tracking_number)
);

if (alreadyFulfilled) {
  return []; // Skip - already synced
}

// Get line item IDs for fulfillment
const lineItemIds = (order.line_items || []).map(li => li.id);

// Map ShipBob carrier names to Shopify carrier names
const carrierMap = {
  'USPS': 'USPS',
  'UPS': 'UPS',
  'FedEx': 'FedEx',
  'DHL': 'DHL Express',
  'DHL eCommerce': 'DHL eCommerce',
  'OnTrac': 'OnTrac',
  'LSO': 'LSO'
};
const shopifyCarrier = carrierMap[shipment.carrier] || shipment.carrier;

return [{
  json: {
    shopify_order_id: order.id,
    order_name: order.name,
    tracking_number: shipment.tracking_number,
    tracking_url: shipment.tracking_url,
    carrier: shopifyCarrier,
    line_item_ids: lineItemIds,
    shipbob_order_id: shipment.shipbob_order_id
  }
}];

// Log successful tracking sync
const fulfillment = $input.first().json.fulfillment;
const shipmentData = $('Skip if Already Fulfilled').first().json;

return [{
  json: {
    status: 'SYNCED',
    shopify_order: shipmentData.order_name,
    tracking_number: shipmentData.tracking_number,
    carrier: shipmentData.carrier,
    fulfillment_id: fulfillment?.id,
    synced_at: new Date().toISOString()
  }
}];

